// YaKit-选色 v0.1.5：由 npm run build 生成。
import { start } from "data:text/javascript;base64,";
start({"css":"/* 复用 YaKit 林系主题，卡片尺寸遵循当前主页。 */\n.yakit-theme-forest {\n  color-scheme: light;\n  --yakit-bg: #F9F8F6;\n  --yakit-card: #FFFFFF;\n  --yakit-input: #F9F8F6;\n  --yakit-card-hover: #F9F8F6;\n  --yakit-accent: #627F49;\n  --yakit-accent-hover: #526C3D;\n  --yakit-accent-soft: rgba(98, 127, 73, 0.10);\n  --yakit-brown: #8A684D;\n  --yakit-text: #35372F;\n  --yakit-text-sub: #72766B;\n  --yakit-text-muted: #9A9D93;\n  --yakit-border: rgba(72, 78, 63, 0.12);\n  --yakit-radius-card: 12px;\n  --yakit-radius-window: 20px;\n}\n\n/* 窗口、卡片和按钮沿用 YaKit 主页尺寸与林系主题。 */\n:host { all: initial; font: 14px/1.5 system-ui, -apple-system, \"Segoe UI\", sans-serif; }\n*, *::before, *::after { box-sizing: border-box; }\n[hidden] { display: none !important; }\nbutton, input, select, textarea { font: inherit; }\nbutton { cursor: pointer; }\nbutton, input, select, textarea { color: var(--yakit-text); }\nbutton:disabled, input:disabled, select:disabled { cursor: default; opacity: .5; }\nbutton:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible { outline: 2px solid var(--yakit-accent); outline-offset: 3px; }\nbutton { display: inline-flex; align-items: center; justify-content: center; gap: 7px; }\n.icon { width: 20px; height: 20px; display: inline-flex; flex: 0 0 auto; }\n.icon svg { width: 100%; height: 100%; }\n.panel { background: var(--yakit-bg); color: var(--yakit-text); width: min(560px, 92vw); height: min(680px, calc(100dvh - 24px)); max-width: none; max-height: none; min-width: 0; min-height: 0; margin: auto; padding: 0; border: 1px solid var(--yakit-border); border-radius: var(--yakit-radius-window); overflow: hidden; display: flex; flex-direction: column; font: 14px/1.5 system-ui, -apple-system, \"Segoe UI\", sans-serif; }\n.panel:not([open]) { display: none; }\n.panel::backdrop { background: rgb(0 0 0 / .35); }\n.panel-header { display: flex; align-items: center; gap: 12px; flex: 0 0 56px; padding: 0 24px; border-bottom: 1px solid var(--yakit-border); }\n.panel-header > .icon { color: var(--yakit-accent); }\nh1 { font-size: 16px; font-weight: 700; margin: 0; flex: 1; }\nh2 { font-size: 14px; font-weight: 600; margin: 0; }\np { margin: 0; }\n.icon-button { width: 32px; height: 32px; padding: 6px; border: 0; border-radius: 50%; background: transparent; color: var(--yakit-text-sub); }\n.icon-button:hover { background: var(--yakit-card-hover); color: var(--yakit-text); }\n.panel-body { min-height: 0; flex: 1; overflow-y: auto; padding: 20px 24px; display: flex; flex-direction: column; gap: 14px; }\n.intro { color: var(--yakit-text-sub); font-size: 12px; }\n.workspace { display: flex; flex-direction: column; gap: 14px; min-height: 0; }\n.controls { display: flex; flex-direction: column; gap: 14px; flex-shrink: 0; min-width: 0; margin: 0; padding: 0; border: 0; }\n.card { background: var(--yakit-card); border: 1px solid var(--yakit-border); border-radius: var(--yakit-radius-card); overflow: hidden; flex-shrink: 0; }\n.card-heading { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 16px; border-bottom: 1px solid var(--yakit-border); font-size: 14px; font-weight: 600; }\n.card-content { display: flex; flex-direction: column; gap: 10px; padding: 14px 16px; }\n.field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.field-grid > label, .field { display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--yakit-text-sub); }\ninput[type=\"number\"], select, textarea { width: 100%; min-width: 0; border: 1px solid var(--yakit-border); background: var(--yakit-input); border-radius: 8px; padding: 7px 9px; }\ninput[type=\"number\"], select { height: 36px; }\n/* 原生下拉沿用林系配色，展开和键盘选择仍由浏览器处理。 */\n@supports (appearance: base-select) {\n  select, select::picker(select) { appearance: base-select; }\n  select { align-items: center; cursor: pointer; }\n  select:hover:enabled { border-color: var(--yakit-accent); }\n  select::picker-icon { color: var(--yakit-text-sub); }\n  select::picker(select) { box-sizing: border-box; width: anchor-size(width); margin-block: 4px; padding: 4px; border: 1px solid var(--yakit-border); border-radius: var(--yakit-radius-card); background: var(--yakit-card); color: var(--yakit-text); font: inherit; }\n  select option { display: flex; align-items: center; gap: 8px; min-height: 36px; padding: 7px 9px; border-radius: 8px; cursor: pointer; }\n  select option:checked { background: var(--yakit-accent-soft); color: var(--yakit-accent); }\n  select option:hover, select option:focus-visible { background: var(--yakit-card-hover); }\n  select option:focus-visible { outline: 2px solid var(--yakit-accent); outline-offset: -2px; }\n  select option::checkmark { order: 1; margin-inline-start: auto; color: var(--yakit-accent); }\n}\n/* 隐藏数字输入框的原生上下按钮，保留数字输入和校验。 */\ninput[type=\"number\"] { -moz-appearance: textfield; appearance: textfield; }\ninput[type=\"number\"]::-webkit-inner-spin-button, input[type=\"number\"]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }\ninput[type=\"checkbox\"] { width: 16px; height: 16px; margin: 0; accent-color: var(--yakit-accent); flex-shrink: 0; }\n.check-label { display: flex; align-items: center; gap: 8px; font-size: 13px; }\n.hint { font-size: 11.5px; color: var(--yakit-text-sub); line-height: 1.5; }\n.small-actions { display: flex; gap: 4px; }\n.small-actions button { padding: 4px 6px; background: transparent; border: 0; border-radius: 6px; font-size: 11px; font-weight: 400; color: var(--yakit-text-sub); }\n.small-actions button:hover { background: var(--yakit-input); color: var(--yakit-text); }\n.group-heading, .group-row { display: grid; grid-template-columns: minmax(55px, 1fr) minmax(0, 1fr) minmax(0, 1fr); align-items: center; gap: 10px; }\n.group-heading { font-size: 11px; color: var(--yakit-text-sub); }\n.group-list { display: flex; flex-direction: column; gap: 8px; }\n.group-row input[type=\"number\"] { height: 32px; padding: 4px 7px; font-size: 12px; }\n.preview-card { min-width: 0; display: flex; flex-direction: column; }\n.badge { font-size: 11px; font-weight: 400; color: var(--yakit-accent); background: var(--yakit-accent-soft); padding: 2px 9px; border-radius: 999px; }\n.preview-content { padding: 14px 16px; flex: 1; }\n.empty-state { min-height: 220px; height: 100%; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 9px; text-align: center; color: var(--yakit-text-sub); }\n.empty-state > .icon { width: 32px; height: 32px; color: var(--yakit-accent); margin-bottom: 3px; }\n.empty-state > span:last-child { font-size: 12px; }\n.result-content { display: flex; flex-direction: column; gap: 10px; }\n.result-summary { font-size: 13px; }\n.result-groups { display: flex; flex-direction: column; gap: 10px; }\n.result-group { border: 1px solid var(--yakit-border); border-radius: 8px; padding: 10px; }\n.result-group-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; }\n.group-state { display: inline-flex; align-items: center; gap: 3px; font-size: 11px; color: var(--yakit-text-sub); }\n.is-passed .group-state { color: var(--yakit-accent); }\n.group-state .icon { width: 14px; height: 14px; }\n.range-text { margin-top: 5px; font-size: 11px; color: var(--yakit-text-sub); overflow-wrap: anywhere; }\n.color-sample { padding: 10px; margin-top: 8px; border-radius: 6px; font-size: 14px; line-height: 1.65; overflow-wrap: anywhere; }\n.output-label { font-size: 12px; font-weight: 600; }\ntextarea { height: 170px; resize: vertical; font: 12px/1.7 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }\n.copy-bar { display: flex; justify-content: flex-end; padding: 10px 16px; border-bottom: 1px solid var(--yakit-border); }\n.secondary-button { background: transparent; border: 1px solid var(--yakit-border); border-radius: 8px; padding: 7px 12px; font-size: 12px; }\n.secondary-button:hover:enabled { background: var(--yakit-card-hover); }\n.secondary-button .icon { width: 16px; height: 16px; }\n.panel-footer { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex: 0 0 68px; padding: 14px 24px; border-top: 1px solid var(--yakit-border); }\n.status { font-size: 12px; color: var(--yakit-text-sub); line-height: 1.4; max-height: 42px; overflow-y: auto; }\n.status.is-error { color: #a43d32; }\n.primary-button { flex-shrink: 0; padding: 10px 22px; border: 0; border-radius: 999px; background: var(--yakit-accent); color: white; font-size: 13px; font-weight: 600; }\n.primary-button:hover:enabled { background: var(--yakit-accent-hover); }\n.primary-button:active:enabled { transform: scale(.97); }\n/* 沿用主页透明轨道，悬浮时显示细滑块。 */\n.panel-body, .controls, .preview-content, textarea, .status { scrollbar-width: thin; scrollbar-color: transparent transparent; }\n.panel-body:hover, .controls:hover, .preview-content:hover, textarea:hover, .status:hover { scrollbar-color: rgba(98, 127, 73, .35) transparent; }\n@supports selector(::-webkit-scrollbar) {\n  .panel-body, .controls, .preview-content, textarea, .status { scrollbar-width: auto; scrollbar-color: auto !important; }\n}\n.panel ::-webkit-scrollbar { width: 4px; height: 4px; }\n.panel ::-webkit-scrollbar-track { background: transparent; border: 0; box-shadow: none; }\n.panel ::-webkit-scrollbar-thumb { background: transparent; border: 0; border-radius: 99px; box-shadow: none; }\n.panel-body:hover::-webkit-scrollbar-thumb, .controls:hover::-webkit-scrollbar-thumb, .preview-content:hover::-webkit-scrollbar-thumb, textarea:hover::-webkit-scrollbar-thumb, .status:hover::-webkit-scrollbar-thumb { background: rgba(98, 127, 73, .35); }\n@media (min-width: 960px) {\n  .panel { width: min(1040px, 92vw); }\n  .panel-body { overflow: hidden; }\n  .workspace { flex: 1; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr); align-items: stretch; }\n  .controls { min-height: 0; overflow-y: auto; padding-right: 3px; }\n  .preview-card { min-height: 0; }\n  .preview-content { min-height: 0; overflow-y: auto; }\n}\n@media (max-width: 480px) {\n  .panel-header { padding-inline: 14px; gap: 8px; }\n  .panel-body { padding: 14px; }\n  .panel-footer { padding-inline: 14px; gap: 10px; }\n  .card-heading, .card-content, .preview-content { padding: 12px; }\n  .copy-bar { padding-inline: 12px; }\n  .primary-button { padding-inline: 14px; }\n}\n\n/* 复用主页的 240ms 进退场，退场结束后再关闭原生 dialog。 */\n.panel { --yakit-view-duration: 240ms; }\n.panel.yakit-panel--opening { animation: yakit-panel-enter var(--yakit-view-duration) ease-out; }\n.panel.yakit-panel--opening::backdrop { animation: yakit-backdrop-enter var(--yakit-view-duration) ease-out; }\n.panel.yakit-panel--closing { animation: yakit-panel-exit var(--yakit-view-duration) ease-in both; }\n.panel.yakit-panel--closing::backdrop { animation: yakit-backdrop-exit var(--yakit-view-duration) ease-in both; }\n.primary-button { transition: background .15s ease, transform .15s ease; }\n.icon-button, .secondary-button, .small-actions button { transition: background .18s ease, color .18s ease; }\n/* 下拉列表沿用主页的淡入缩放，退出时保留顶层显示直到动效结束。 */\n@supports (appearance: base-select) {\n  select::picker(select) {\n    opacity: 0;\n    transform: scale(.98);\n    transition: opacity var(--yakit-view-duration) ease-in,\n      transform var(--yakit-view-duration) ease-in,\n      display var(--yakit-view-duration) allow-discrete,\n      overlay var(--yakit-view-duration) allow-discrete;\n  }\n  select:open::picker(select) {\n    opacity: 1;\n    transform: none;\n    transition-timing-function: ease-out;\n  }\n  @starting-style {\n    select:open::picker(select) { opacity: 0; transform: scale(.98); }\n  }\n  select::picker-icon { transition: rotate .18s ease; }\n  select:open::picker-icon { rotate: 180deg; }\n}\n@keyframes yakit-panel-enter { from { opacity: 0; transform: scale(.98); } to { opacity: 1; transform: none; } }\n@keyframes yakit-backdrop-enter { from { opacity: 0; } to { opacity: 1; } }\n@keyframes yakit-panel-exit { to { opacity: 0; transform: scale(.98); } }\n@keyframes yakit-backdrop-exit { to { opacity: 0; } }\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after, .panel::backdrop { animation: none !important; transition: none !important; }\n  select::picker(select), select::picker-icon { animation: none !important; transition: none !important; }\n}\n","icons":{"palette":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"\n     fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"\n     stroke-linecap=\"round\" stroke-linejoin=\"round\">\n  <!-- 圆润盘身与四个实心色点在小尺寸下也能清楚辨认。 -->\n  <path d=\"M12 3C6.9 3 3 6.8 3 11.5S6.8 21 12 21h.8c1.8 0 2.6-2.1 1.4-3.4l-.4-.5c-.9-1-.2-2.6 1.2-2.6h2.2c2.3 0 3.8-1.5 3.8-3.7C21 6.4 16.9 3 12 3Z\"/>\n  <g fill=\"currentColor\" stroke=\"none\">\n    <circle cx=\"7.1\" cy=\"9.2\" r=\"1.3\"/>\n    <circle cx=\"10.9\" cy=\"6.9\" r=\"1.3\"/>\n    <circle cx=\"15.3\" cy=\"7.9\" r=\"1.3\"/>\n    <circle cx=\"6.9\" cy=\"13.9\" r=\"1.3\"/>\n  </g>\n</svg>\n","close":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"\n     fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"\n     stroke-linecap=\"round\">\n  <path d=\"M6 6l12 12M18 6 6 18\"/>\n</svg>","test":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"\n     fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"\n     stroke-linecap=\"round\" stroke-linejoin=\"round\">\n  <path d=\"M3.5 12s3.2-5.5 8.5-5.5S20.5 12 20.5 12s-3.2 5.5-8.5 5.5S3.5 12 3.5 12Z\"/>\n  <circle cx=\"12\" cy=\"12\" r=\"2.6\"/>\n</svg>","copy":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"13\" rx=\"2\"/><path d=\"M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3\"/></svg>\n","check":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m5 12 4.5 4.5L19 7\"/></svg>\n"}});
